package net.officefloor.hq.app.paste;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.claim.ClaimRules;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the paste box from the body: each non-blank line is name,amount,date,note — the note is the rest of the
 * line, so it may hold commas; the date and the note may be blank or absent. Checks every line's claim exactly
 * as the claim form would (it corrects nothing), refusing the whole paste when any line fails or there is none.
 */
public class ValidatePaste {
    public void validate(@RequestBody PasteRequest request, Out<PastedLines> linesOut) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PastedLine> lines = new ArrayList<>();
        int at = 0;
        for (String line : text.split("\\r?\\n")) {
            at++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            String name = fields[0].trim();
            if (name.isEmpty() || fields.length < 2) {
                throw new InvalidClaimException("Line " + at + ": a line is name,amount,date,note.");
            }
            ClaimInput claim;
            try {
                claim = ClaimRules.check(fields[1], fields.length > 2 ? fields[2] : null,
                        fields.length > 3 ? fields[3] : null, null);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + at + ": " + e.getMessage());
            }
            lines.add(new PastedLine(name, claim));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
        }
        linesOut.set(new PastedLines(List.copyOf(lines)));
    }
}
package net.officefloor.hq.app.paste;

import java.util.List;

/** Every line of the paste box, in order. */
public record PastedLines(List<PastedLine> lines) {
}
package net.officefloor.hq.app.paste;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRules;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Finds each line's person on the sheet, ignoring case, and makes its DRAFT claim by the claim form's rules —
 * all of them before any is stored, so a refused line adds nothing. Then adds the claims in order, each recorded
 * and logged as the claim form records and logs it.
 */
public class AddPastedClaims {
    public void add(@Val PastedLines pasted, @Val Sheet sheet, PersonRepository people, ClaimRepository claims,
            PeriodRepository periods, PersonGradeRepository grades, RateRepository rates, ClaimLogRepository log,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
            Out<PastedClaims> addedOut) throws InvalidClaimException {
        List<Person> onSheet = people.findBySheetIdOrderByIdAsc(sheet.getId());
        List<Person> persons = new ArrayList<>();
        List<Claim> made = new ArrayList<>();
        int at = 0;
        for (PastedLine line : pasted.lines()) {
            at++;
            Person person = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(line.name())).findFirst()
                    .orElse(null);
            if (person == null) {
                throw new InvalidClaimException("Line " + at + ": " + line.name() + " is not on the sheet.");
            }
            try {
                made.add(ClaimRules.make(line.claim(), sheet, person, claims, periods, grades));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + at + ": " + e.getMessage());
            }
            persons.add(person);
        }
        String by = AuditUser.decode(user);
        for (int i = 0; i < made.size(); i++) {
            Claim claim = claims.saveAndFlush(made.get(i));
            ClaimRules.auditAdded(claim, persons.get(i).getName(), by, audit);
            ClaimRules.log(claim, sheet, log, people, rates, grades, by);
        }
        addedOut.set(new PastedClaims(made.size()));
    }
}
package net.officefloor.hq.app.paste;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPastedClaims {
    public void respond(@Val PastedClaims added, ObjectResponse<PastedClaims> response) {
        response.send(added);
    }
}

